      "win": {
        "text": "津橋が修復されたその瞬間、十万の呉軍はついに鉄壁の陣形を完成させた。城頭からそれを見届けた張遼は、刀を鞘へと収めた。『呉兵が陣を整えたか。もはや出撃すべきにあらず』血染めの凌統が橋を渡ると、孫権は自ら馬を降りてその手を取った。建業への帰途に笑みはなく、ただ孫権の重き呟きが響いた。『孤は合肥を生涯忘れぬ。張文遠の名を深く刻み込んだぞ』",
        "hook": "逍遥津の痛打を受け、江東は矛先を完全に荊州へと戻した。そして劉備が打ち鳴らす漢中の軍鼓は、すでに定軍山の下へと響き渡っていた。"
      },
      "loss": {
        "text": "十万の陣列も、八百の猛威を食い止めることは叶わなかった。津橋が断ち切られた瞬間、凌統の三百の親衛隊は対岸で討ち死にし、張遼の名は江東の童児の泣き声を止める恐怖の象徴として刻まれた。",
        "clue": "史官の教訓・張遼の勝因は兵力にあらず『混乱を突く奇襲』にあり。再戦時はまず陣形を整えて渡橋せよ。陣が乱れねば、敵は出撃を躊躇う。",
        "clueFx": "keenEye"
      },
