        "text": "夏侯淵の神速に翻弄され、張郃の変幻に退路を断たれた。二将が衝突するのを待つはずが、二つの異なる波に呑まれ、老将の刃は鞘を離れることすら叶わなかった。",
        "clue": "史官の教訓・敵将は交互に速攻と変陣を仕掛けてくる。一方が動くのを見届けてから次を読め。再戦時は看破上昇。",
        "clueFx": "keenEye"
